#include <iostream>
using namespace std;
int main() {
    int a = 10;
    int* p = &a;
    cout << p << endl;    // Address of a
    cout << *p << endl;   // Value of a: 10
    cout << &p << endl;   // Address of pointer p itself
    int x = a;
    x = 40;
    cout << a << endl;    // Still 10
    *p = 50;
    cout << a << endl;    // 50
    return 0;
}

